## Extension Points

### 1. Custom Partitioner

Implement custom partitioning logic:

```rust
use eventstream::Partitioner;

pub struct CustomPartitioner {
    // Your fields
}

impl<K> Partitioner<K> for CustomPartitioner
where
    K: Hash,
{
    fn partition(&self, key: &Option<K>, num_partitions: u32) -> u32 {
        // Your partitioning logic
        match key {
            Some(k) => {
                // Custom hash
                let hash = custom_hash(k);
                hash % num_partitions
            }
            None => 0,
        }
    }
}

// Use it
let producer = Producer::builder()
    .partitioner(CustomPartitioner { /* ... */ })
    .build()?;
```

### 2. Custom Serializer

Implement your own serialization:

```rust
use eventstream::CustomSerializer;

pub struct MySerializer;

impl CustomSerializer for MySerializer {
    fn serialize<T: Serialize>(&self, value: &T) -> Result<Vec<u8>> {
        // Your serialization logic
        let bytes = my_serialize(value)?;
        Ok(bytes)
    }

    fn deserialize<'de, T: Deserialize<'de>>(&self, bytes: &'de [u8]) -> Result<T> {
        // Your deserialization logic
        let value = my_deserialize(bytes)?;
        Ok(value)
    }
}

// Use it
let producer = Producer::builder()
    .key_serializer(Serializer::Custom(Box::new(MySerializer)))
    .build()?;
```

### 3. Custom Storage Backend

Implement a new storage backend:

```rust
use eventstream::storage::Storage;

pub struct MyStorageBackend {
    // Your fields
}

#[async_trait]
impl Storage for MyStorageBackend {
    async fn write_record(
        &self,
        topic: &str,
        partition: u32,
