    // Produce
    let producer = topic.producer()?;
    producer.send(Event::new(
        Some("key".to_string()),
        "value".to_string()
    )).await?;

    // Consume
    let consumer = topic.consumer()?;
    let events = consumer.fetch().max_records(1).await?;

    assert_eq!(events.len(), 1);
    assert_eq!(events[0].key, Some("key".to_string()));
    assert_eq!(events[0].value, "value".to_string());

    // Cleanup
