## Performance Tuning

### 1. Producer Tuning

```rust
// High throughput
let producer = Producer::builder()
    .batch_size(100_000)     // Larger batches
    .linger(Duration::from_millis(100))  // Wait longer
    .compression(Compression::Zstd)  // Compress
    .buffer_memory(64 * 1024 * 1024)  // 64MB buffer
    .build()?;

// Low latency
let producer = Producer::builder()
    .batch_size(16 * 1024)    // Smaller batches
    .linger(Duration::from_millis(0))  // No waiting
    .compression(Compression::None)  // No compression
    .build()?;
```

### 2. Consumer Tuning

```rust
// High throughput
let consumer = Consumer::builder()
    .fetch_min_bytes(1024 * 1024)  // 1MB minimum
    .fetch_max_wait_ms(1000)  // Wait up to 1s
    .max_poll_records(1000)  // More records
    .build()?;

// Low latency
let consumer = Consumer::builder()
    .fetch_min_bytes(1)  // As little as possible
    .fetch_max_wait_ms(100)  // Wait 100ms max
    .max_poll_records(100)  // Fewer records
    .build()?;
```

### 3. Storage Tuning

```rust
// High throughput
let config = StorageConfig {
    segment_bytes: 1_000_000_000,  // 1GB segments
    flush_messages: 100_000,  // Flush less often
    flush_ms: 10_000,  // Flush every 10s
};

// Low latency
